import numpy as np
from scipy.ndimage import label, find_objects
A=np.load('source_pixels.npz')['rgb'].astype(int)
for t in range(1,96):
 d=np.max(abs(A[t]-A[t-1]),2)
 m=d>12
 lab,n=label(m)
 cs=[]
 for i,sl in enumerate(find_objects(lab),1):
  if sl:
   c=np.sum(lab[sl]==i)
   if c>=2: cs.append((c,(sl[1].start,sl[0].start,sl[1].stop-1,sl[0].stop-1),round(d[sl][lab[sl]==i].mean())))
 cs=sorted(cs,reverse=True)[:5]
 if cs: print(f'{t:02}',cs)
